#include <iostream>
#include <vector>
#include <string>
#include <queue>
#include <functional>
#include <utility>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long h;
    long long w;
    cin >> h >> w;
    vector<vector<long long>> cost(h, vector<long long>(w));
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            cin >> cost[i][j];
        }
    }

    const long long INF = 1000000000000000000LL;
    vector<vector<long long>> dist(h, vector<long long>(w, INF));
    dist[0][0] = cost[0][0];
    typedef pair<long long, pair<int, int>> Item;
    priority_queue<Item, vector<Item>, greater<Item>> heap;
    heap.push({cost[0][0], {0, 0}});
    int dx[4] = {1, -1, 0, 0}, dy[4] = {0, 0, 1, -1};
    while (!heap.empty()) {
        Item top = heap.top();
        heap.pop();
        int x = top.second.first, y = top.second.second;
        if (top.first > dist[x][y]) continue;
        for (int d = 0; d < 4; d++) {
            int p = x + dx[d], q = y + dy[d];
            if (p >= 0 && p < h && q >= 0 && q < w && top.first + cost[p][q] < dist[p][q]) {
                dist[p][q] = top.first + cost[p][q];
                heap.push({dist[p][q], {p, q}});
            }
        }
    }
    cout << dist[h - 1][w - 1] << "\n";

    return 0;
}

